def two_values(nums, k):
    seen = set()
    for x in nums:
        if x > k:
            continue
        if k - x in seen:
            return [k - x, x]
        seen.add(x)
    return []

from functools import lru_cache


def stairs(n):
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def ways(k):
        if k < 0:
            return 0
        if k == 0:
            return 1
        return (ways(k - 1) + ways(k - 2) + ways(k - 3)) % MOD

    return ways(n)
